import{_ as r,o as a,c as o,ae as e}from"./chunks/framework.Dn7Y7LSn.js";const _=JSON.parse('{"title":"Laravel Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"laravel/introduction.md","filePath":"laravel/introduction.md"}'),n={name:"laravel/introduction.md"};function i(l,t,s,d,c,u){return a(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="laravel-introduction" tabindex="-1">Laravel Introduction <a class="header-anchor" href="#laravel-introduction" aria-label="Permalink to &quot;Laravel Introduction&quot;">​</a></h1><p>লারাভেল (Laravel) হলো বর্তমান সময়ের সবচেয়ে জনপ্রিয় এবং শক্তিশালী পিএইচপি ফ্রেমওয়ার্ক। এটি মূলত <strong>MVC (Model-View-Controller)</strong> আর্কিটেকচার প্যাটার্ন অনুসরণ করে।</p><h3 id="লারাভেল-কেন-শিখবেন" tabindex="-1">লারাভেল কেন শিখবেন? <a class="header-anchor" href="#লারাভেল-কেন-শিখবেন" aria-label="Permalink to &quot;লারাভেল কেন শিখবেন?&quot;">​</a></h3><p>১. <strong>সহজ সিনট্যাক্স:</strong> লারাভেলের কোড পড়া মানুষের ভাষার মতই সহজ এবং পরিষ্কার। ২. <strong>বিল্ট-ইন ফিচার:</strong> অথেন্টিকেশন, রাউটিং, সেশন, এবং ক্যাশিং এর মত ফিচারগুলো লারাভেলে আগে থেকেই তৈরি থাকে। ৩. <strong>Eloquent ORM:</strong> ডাটাবেজের সাথে কাজ করার জন্য লারাভেলে চমৎকার একটি ORM রয়েছে। ৪. <strong>বিশাল কমিউনিটি:</strong> লারাভেলের রয়েছে অনেক বড় একটি কমিউনিটি, ফলে যেকোনো সমস্যায় সহজেই সমাধান পাওয়া যায়।</p><h3 id="শেখার-পূর্বশর্ত" tabindex="-1">শেখার পূর্বশর্ত <a class="header-anchor" href="#শেখার-পূর্বশর্ত" aria-label="Permalink to &quot;শেখার পূর্বশর্ত&quot;">​</a></h3><p>লারাভেল শুরু করার আগে আপনার নিচের বিষয়গুলো সম্পর্কে পরিষ্কার ধারণা থাকা উচিত:</p><ul><li><strong>Core PHP</strong></li><li><strong>Object-Oriented Programming (OOP)</strong></li><li><strong>Composer</strong> (PHP Dependency Manager)</li></ul><hr><p><em>লারাভেলের পরবর্তী টিউটোরিয়ালগুলো খুব শীঘ্রই যোগ করা হবে।</em></p>',9)])])}const g=r(n,[["render",i]]);export{_ as __pageData,g as default};
